def is_not_prime(n):
    """
    Returns True if n is NOT a prime number, False if n is prime.
    """
    if n < 2:
        return True
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return True
    return False

def differ_At_One_Bit_Pos(a, b):
    xor = a ^ b
    return xor != 0 and (xor & (xor - 1)) == 0

def remove_Occ(s, ch):
    """
    Remove the first and last occurrence of a given character from the string.
    """
    first = s.find(ch)
    if first == -1:
        return s
    last = s.rfind(ch)

    result = []
    for i, c in enumerate(s):
        if i == first or i == last:
            continue
        result.append(c)
    return "".join(result)

def check(num):
    reverse_num = int(str(num)[::-1])
    return num == 2 * reverse_num - 1

def is_Monotonic(A):
    return (all(A[i] <= A[i + 1] for i in range(len(A) - 1)) or
            all(A[i] >= A[i + 1] for i in range(len(A) - 1)))
